// 时间复杂度: O(n)
// 空间复杂度: O(1)
function moveZeroes(nums: number[]): void {
  let insertIndex = 0;

  for (const num of nums) {
    if (num !== 0) {
      nums[insertIndex] = num;
      insertIndex++;
    }
  }

  while (insertIndex < nums.length) {
    nums[insertIndex] = 0;
    insertIndex++;
  }
}

