// 时间复杂度: O(n)
// 空间复杂度: O(1)
function maxProfit(prices: number[]): number {
  let minPrice = Number.POSITIVE_INFINITY;
  let bestProfit = 0;

  for (const price of prices) {
    if (price < minPrice) {
      minPrice = price;
    } else if (price - minPrice > bestProfit) {
      bestProfit = price - minPrice;
    }
  }

  return bestProfit;
}

