// 时间复杂度: O(n)
// 空间复杂度: O(n)
function isValidBrackets(s: string): boolean {
  const pairs = new Map<string, string>([
    [")", "("],
    ["]", "["],
    ["}", "{"]
  ]);
  const stack: string[] = [];

  for (let i = 0; i < s.length; i++) {
    const ch = s.charAt(i);
    if (ch === "(" || ch === "[" || ch === "{") {
      stack.push(ch);
    } else {
      const expected = pairs.get(ch);
      if (expected === undefined || stack.pop() !== expected) {
        return false;
      }
    }
  }

  return stack.length === 0;
}

