// 时间复杂度: O(n)
// 空间复杂度: O(k)，k 为字符集大小
function isIsomorphic(s: string, t: string): boolean {
  if (s.length !== t.length) {
    return false;
  }

  const sToT = new Map<string, string>();
  const tToS = new Map<string, string>();

  for (let i = 0; i < s.length; i++) {
    const a = s.charAt(i);
    const b = t.charAt(i);

    const mappedB = sToT.get(a);
    if (mappedB !== undefined) {
      if (mappedB !== b) {
        return false;
      }
    } else {
      sToT.set(a, b);
    }

    const mappedA = tToS.get(b);
    if (mappedA !== undefined) {
      if (mappedA !== a) {
        return false;
      }
    } else {
      tToS.set(b, a);
    }
  }

  return true;
}

