// 时间复杂度: O(n)
// 空间复杂度: O(1)
function climbStairs(n: number): number {
  if (n <= 2) {
    return n;
  }

  let prev = 1;
  let curr = 2;

  for (let i = 3; i <= n; i++) {
    const next = prev + curr;
    prev = curr;
    curr = next;
  }

  return curr;
}

