// 时间复杂度: O(n)
// 空间复杂度: O(1)
function majorityElement(nums: number[]): number {
  let candidate: number = nums[0];
  let count = 0;

  for (const num of nums) {
    if (count === 0) {
      candidate = num;
    }
    count += num === candidate ? 1 : -1;
  }

  return candidate;
}

