// 时间复杂度: O(n)
// 空间复杂度: O(1)（不计返回数组）
function plusOne(digits: number[]): number[] {
  for (let i = digits.length - 1; i >= 0; i--) {
    if (digits[i] < 9) {
      digits[i] += 1;
      return digits;
    }
    digits[i] = 0;
  }

  digits.unshift(1);
  return digits;
}

