// 时间复杂度: O(n)
// 空间复杂度: O(min(n, 字符集大小))
function lengthOfLongestSubstring(s: string): number {
  const seen = new Set<string>();
  let left = 0;
  let maxLen = 0;

  for (let right = 0; right < s.length; right++) {
    const ch = s.charAt(right);
    while (seen.has(ch)) {
      seen.delete(s.charAt(left));
      left++;
    }
    seen.add(ch);
    maxLen = Math.max(maxLen, right - left + 1);
  }

  return maxLen;
}

