// 时间复杂度: O(n + m)
// 空间复杂度: O(1)
function findAnagrams(s: string, p: string): number[] {
  if (p.length > s.length) {
    return [];
  }

  const need: number[] = new Array(26).fill(0);
  const window: number[] = new Array(26).fill(0);
  const result: number[] = [];

  for (let i = 0; i < p.length; i++) {
    need[p.charCodeAt(i) - 97]++;
  }

  let left = 0;

  for (let right = 0; right < s.length; right++) {
    window[s.charCodeAt(right) - 97]++;

    if (right - left + 1 > p.length) {
      window[s.charCodeAt(left) - 97]--;
      left++;
    }

    if (right - left + 1 === p.length) {
      let matched = true;
      for (let i = 0; i < 26; i++) {
        if (need[i] !== window[i]) {
          matched = false;
          break;
        }
      }
      if (matched) {
        result.push(left);
      }
    }
  }

  return result;
}

