// 时间复杂度: O(n)
// 空间复杂度: O(n)
function subarraySum(nums: number[], k: number): number {
  const prefix = new Map<number, number>();
  prefix.set(0, 1);
  let sum = 0;
  let result = 0;

  for (const num of nums) {
    sum += num;
    result += prefix.get(sum - k) ?? 0;
    prefix.set(sum, (prefix.get(sum) ?? 0) + 1);
  }

  return result;
}

