// 时间复杂度: O(n)
// 空间复杂度: O(n)
function evalRPN(tokens: string[]): number {
  const stack: number[] = [];

  for (const token of tokens) {
    if (token === "+" || token === "-" || token === "*" || token === "/") {
      const b = stack.pop() as number;
      const a = stack.pop() as number;

      if (token === "+") {
        stack.push(a + b);
      } else if (token === "-") {
        stack.push(a - b);
      } else if (token === "*") {
        stack.push(a * b);
      } else {
        stack.push(Math.trunc(a / b));
      }
    } else {
      stack.push(Number(token));
    }
  }

  return stack[0];
}

