// 时间复杂度: O(n + 解码结果长度)
// 空间复杂度: O(n + 解码结果长度)
function decodeString(s: string): string {
  const countStack: number[] = [];
  const stringStack: string[] = [];
  let current = "";
  let count = 0;

  for (const ch of s) {
    if (ch >= "0" && ch <= "9") {
      count = count * 10 + Number(ch);
    } else if (ch === "[") {
      countStack.push(count);
      stringStack.push(current);
      count = 0;
      current = "";
    } else if (ch === "]") {
      const repeatTimes = countStack.pop() as number;
      const previous = stringStack.pop() as string;
      current = previous + current.repeat(repeatTimes);
    } else {
      current += ch;
    }
  }

  return current;
}

