// 时间复杂度: push O(1)，pop/peek 均摊 O(1)，empty O(1)
// 空间复杂度: O(n)
class MyQueue {
  private inStack: number[];
  private outStack: number[];

  constructor() {
    this.inStack = [];
    this.outStack = [];
  }

  push(x: number): void {
    this.inStack.push(x);
  }

  private transfer(): void {
    if (this.outStack.length === 0) {
      while (this.inStack.length > 0) {
        this.outStack.push(this.inStack.pop() as number);
      }
    }
  }

  pop(): number {
    this.transfer();
    return this.outStack.pop() as number;
  }

  peek(): number {
    this.transfer();
    return this.outStack[this.outStack.length - 1];
  }

  empty(): boolean {
    return this.inStack.length === 0 && this.outStack.length === 0;
  }
}

function runMyQueue(): void {
  const queue = new MyQueue();
  queue.push(1);
  queue.push(2);
  queue.peek();
  queue.pop();
  queue.empty();
}

runMyQueue();

// 时间复杂度: O(n)
// 空间复杂度: O(n)
function trap(height: number[]): number {
  const stack: number[] = [];
  let water = 0;

  for (let i = 0; i < height.length; i++) {
    while (stack.length > 0 && height[i] > height[stack[stack.length - 1]]) {
      const bottom = stack.pop() as number;

      if (stack.length === 0) {
        break;
      }

      const left = stack[stack.length - 1];
      const width = i - left - 1;
      const boundedHeight = Math.min(height[left], height[i]) - height[bottom];
      water += width * boundedHeight;
    }

    stack.push(i);
  }

  return water;
}

