  next: RandomNode | null;
  random: RandomNode | null;
  constructor(val?: number, next?: RandomNode | null, random?: RandomNode | null) {
    this.val = val === undefined ? 0 : val;
    this.next = next === undefined ? null : next;
    this.random = random === undefined ? null : random;
  }
}

function copyRandomList(head: RandomNode | null): RandomNode | null {
  if (head === null) return null;

  const map = new Map<RandomNode, RandomNode>();
  let current: RandomNode | null = head;

  while (current !== null) {
    map.set(current, new RandomNode(current.val));
    current = current.next;
  }

  current = head;
  while (current !== null) {
    const copied = map.get(current);
    if (copied !== undefined) {
      copied.next = current.next === null ? null : map.get(current.next) ?? null;
      copied.random = current.random === null ? null : map.get(current.random) ?? null;
    }
    current = current.next;
  }

  return map.get(head) ?? null;
}

