function reorderList(head: ListNode | null): void {
  if (head === null || head.next === null) return;

  let slow: ListNode = head;
  let fast: ListNode | null = head;

  while (fast !== null && fast.next !== null && fast.next.next !== null) {
    slow = slow.next as ListNode;
    fast = fast.next.next;
  }

  let second: ListNode | null = slow.next;
  slow.next = null;

  let prev: ListNode | null = null;
  let current: ListNode | null = second;

  while (current !== null) {
    const next = current.next;
    current.next = prev;
    prev = current;
    current = next;
  }

  second = prev;
  let first: ListNode | null = head;
  let secondCurrent: ListNode | null = second;

  while (secondCurrent !== null && first !== null) {
    const firstNext = first.next;
    const secondNext = secondCurrent.next;

    first.next = secondCurrent;
    secondCurrent.next = firstNext;

    first = firstNext;
    secondCurrent = secondNext;
  }
}

