// 时间复杂度: O(n^2)
// 空间复杂度: O(h)
class TreeNode {
  val: number;
  left: TreeNode | null;
  right: TreeNode | null;

  constructor(val: number, left: TreeNode | null = null, right: TreeNode | null = null) {
    this.val = val;
    this.left = left;
    this.right = right;
  }
}

function pathSum(root: TreeNode | null, targetSum: number): number[][] {
  const result: number[][] = [];
  const path: number[] = [];

  function dfs(node: TreeNode | null, remaining: number): void {
    if (node === null) return;

    path.push(node.val);
    const next = remaining - node.val;

    if (node.left === null && node.right === null && next === 0) {
      result.push(path.slice());
    } else {
      dfs(node.left, next);
      dfs(node.right, next);
    }

    path.pop();
  }

  dfs(root, targetSum);
  return result;
}

