// 时间复杂度: O(V + E)
// 空间复杂度: O(V)
class GraphNode {
  val: number;
  neighbors: GraphNode[];

  constructor(val: number) {
    this.val = val;
    this.neighbors = [];
  }
}

function buildGraph(adjList: number[][]): GraphNode | null {
  if (adjList.length === 0) return null;
  const nodes: GraphNode[] = [];
  for (let i = 0; i <= adjList.length; i++) {
    nodes.push(new GraphNode(i));
  }
  for (let i = 0; i < adjList.length; i++) {
    const current = nodes[i + 1];
    for (const neighborVal of adjList[i]) {
      current.neighbors.push(nodes[neighborVal]);
    }
  }
  return nodes[1];
}

function cloneGraph(node: GraphNode | null): GraphNode | null {
  if (node === null) return null;
  const visited = new Map<GraphNode, GraphNode>();

  function dfs(current: GraphNode): GraphNode {
    const existing = visited.get(current);
    if (existing !== undefined) return existing;

    const copy = new GraphNode(current.val);
    visited.set(current, copy);

    for (const neighbor of current.neighbors) {
      copy.neighbors.push(dfs(neighbor));
    }
    return copy;
  }

  return dfs(node);
}

cloneGraph(buildGraph([[2,4],[1,3],[2,4],[1,3]]));

// 时间复杂度: O(V + E)
// 空间复杂度: O(V + E)
function canFinish(numCourses: number, prerequisites: number[][]): boolean {
  const graph: number[][] = Array.from({ length: numCourses }, () => []);
  const indegree: number[] = new Array<number>(numCourses).fill(0);

  for (const [course, prerequisite] of prerequisites) {
    graph[prerequisite].push(course);
    indegree[course]++;
  }

  const queue: number[] = [];
  for (let i = 0; i < numCourses; i++) {
    if (indegree[i] === 0) queue.push(i);
  }

  let head = 0;
  let completed = 0;
  while (head < queue.length) {
    const current = queue[head++];
    completed++;
    for (const next of graph[current]) {
      indegree[next]--;
      if (indegree[next] === 0) queue.push(next);
    }
  }

  return completed === numCourses;
}

