// 时间复杂度: O(n * 2^n)
// 空间复杂度: O(n)（递归栈，不计结果）
function subsets(nums: number[]): number[][] {
  const result: number[][] = [];
  const path: number[] = [];
  const sorted = nums.slice().sort((a, b) => a - b);

  const backtrack = (start: number): void => {
    result.push(path.slice());

    for (let i = start; i < sorted.length; i++) {
      if (i > start && sorted[i] === sorted[i - 1]) continue;

      path.push(sorted[i]);
      backtrack(i + 1);
      path.pop();
    }
  };

  backtrack(0);
  return result;
}

