// 时间复杂度: O(n^(target / min(candidates)))（最坏情况）
// 空间复杂度: O(target / min(candidates))（递归栈，不计结果）
function combinationSum(candidates: number[], target: number): number[][] {
  const result: number[][] = [];
  const path: number[] = [];
  const sorted = candidates.slice().sort((a, b) => a - b);

  const backtrack = (start: number, remain: number): void => {
    if (remain === 0) {
      result.push(path.slice());
      return;
    }

    for (let i = start; i < sorted.length; i++) {
      if (sorted[i] > remain) break;

      path.push(sorted[i]);
      backtrack(i, remain - sorted[i]);
      path.pop();
    }
  };

  backtrack(0, target);
  return result;
}

