// 时间复杂度: O(4^n / sqrt(n))（结果数量与构造开销）
// 空间复杂度: O(n)（递归栈，不计结果）
function generateParenthesis(n: number): string[] {
  const result: string[] = [];
  const path: string[] = [];

  const backtrack = (open: number, close: number): void => {
    if (path.length === n * 2) {
      result.push(path.join(''));
      return;
    }

    if (open < n) {
      path.push('(');
      backtrack(open + 1, close);
      path.pop();
    }

    if (close < open) {
      path.push(')');
      backtrack(open, close + 1);
      path.pop();
    }
  };

  backtrack(0, 0);
  return result;
}

