// 时间复杂度: O(m * n)
// 空间复杂度: O(n)
function uniquePaths(m: number, n: number): number {
  if (m <= 0 || n <= 0) {
    return 0;
  }

  const dp: number[] = new Array<number>(n).fill(1);

  for (let i = 1; i < m; i++) {
    for (let j = 1; j < n; j++) {
      dp[j] += dp[j - 1];
    }
  }

  return dp[n - 1];
}

