// 时间复杂度: O(n * L^2)，其中 n 为字符串长度，L 为字典单词最大长度
// 空间复杂度: O(n + m)，其中 m 为字典总字符数
function wordBreak(s: string, wordDict: string[]): boolean {
  const dict = new Set<string>(wordDict);
  let maxLen = 0;

  for (const word of wordDict) {
    if (word.length > maxLen) {
      maxLen = word.length;
    }
  }

  const n = s.length;
  const dp: boolean[] = new Array<boolean>(n + 1).fill(false);
  dp[0] = true;

  for (let i = 1; i <= n; i++) {
    const start = Math.max(0, i - maxLen);

    for (let j = start; j < i; j++) {
      if (dp[j] && dict.has(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }

  return dp[n];
}

