// 时间复杂度: O(m * n)
// 空间复杂度: O(n)
function editDistance(word1: string, word2: string): number {
  const m = word1.length;
  const n = word2.length;
  let prev: number[] = new Array<number>(n + 1);
  for (let j = 0; j <= n; j++) {
    prev[j] = j;
  }

  for (let i = 1; i <= m; i++) {
    const curr: number[] = new Array<number>(n + 1);
    curr[0] = i;
    for (let j = 1; j <= n; j++) {
      if (word1[i - 1] === word2[j - 1]) {
        curr[j] = prev[j - 1];
      } else {
        curr[j] = 1 + Math.min(prev[j], curr[j - 1], prev[j - 1]);
      }
    }
    prev = curr;
  }

  return prev[n];
}
