// 时间复杂度: O(m * n)
// 空间复杂度: O(n)
function longestCommonSubsequence(text1: string, text2: string): number {
  const m = text1.length;
  const n = text2.length;
  const dp: number[] = new Array<number>(n + 1).fill(0);

  for (let i = 1; i <= m; i++) {
    let prevDiagonal = 0;
    for (let j = 1; j <= n; j++) {
      const temp = dp[j];
      if (text1[i - 1] === text2[j - 1]) {
        dp[j] = prevDiagonal + 1;
      } else {
        dp[j] = Math.max(dp[j], dp[j - 1]);
      }
      prevDiagonal = temp;
    }
  }

  return dp[n];
}
